// Extract message data
const payload = msg.payload || {};
let chatId = payload.chatId;
const messageType = payload.type;
let text = (payload.content || '').trim();

// Get user info
const originalMsg = msg.originalMessage || {};
let userId = originalMsg.from ? originalMsg.from.id : null;
const messageId = originalMsg.message_id;

// Handle callback queries
let answerCallback = null;
if (messageType === 'callback_query') {
    text = payload.data || payload.callback_data || payload.content || 
           (originalMsg.data ? originalMsg.data : '') || '';

    if (!chatId) {
        if (originalMsg.message && originalMsg.message.chat) {
            chatId = originalMsg.message.chat.id;
        } else if (originalMsg.chat) {
            chatId = originalMsg.chat.id;
        }
    }

    if (originalMsg.from) {
        userId = originalMsg.from.id;
    }

    const callbackQueryId = payload.callback_query_id || payload.id || 
                            (originalMsg.id ? originalMsg.id.toString() : null) ||
                            (originalMsg.query_id ? originalMsg.query_id.toString() : null);

    if (callbackQueryId) {
        answerCallback = {
            payload: {
                callback_query_id: callbackQueryId,
                text: '',
                show_alert: false
            },
            topic: 'answerCallbackQuery'
        };
    }
}

// Check if it's a valid message
if ((messageType !== 'message' && messageType !== 'callback_query') || !text || !chatId) {
    return [null, null, null, null, null, null, answerCallback];
}

// Store chat ID
if (!global.get('aquarium_telegram_chat_ids')) {
    global.set('aquarium_telegram_chat_ids', []);
}
const chatIds = global.get('aquarium_telegram_chat_ids');
if (!chatIds.includes(chatId)) {
    chatIds.push(chatId);
    global.set('aquarium_telegram_chat_ids', chatIds);
}

// Parse command
const command = text.split(' ')[0].toLowerCase();
const args = text.split(' ').slice(1);

// Only handle aquarium-specific commands
if (!command.startsWith('/aquarium_')) {
    return [null, null, null, null, null, null, answerCallback];
}

const requestId = Date.now().toString(36) + Math.random().toString(36).substr(2);
node.warn(`[${requestId}] Aquarium Command: ${command} from chat ${chatId}`);

// Prepare message
msg.requestId = requestId;
msg.chatId = chatId;
msg.telegram = {
    chatId: chatId,
    userId: userId,
    messageId: messageId,
    command: command,
    args: args,
    originalText: text
};

// Initialize array with null positions for ALL 6 outputs
let output = [null, null, null, null, null, null, null];

// Route to handler
switch(command) {
    case '/aquarium_on':
        output[0] = msg;
        output[6] = answerCallback;
        break;
    case '/aquarium_off':
        output[1] = msg;
        output[6] = answerCallback;
        break;
    case '/aquarium_toggle':
        output[2] = msg;
        output[6] = answerCallback;
        break;
    case '/aquarium_status':
        output[3] = msg;
        output[6] = answerCallback;
        break;
    case '/aquarium_help':
        output[4] = msg;
        output[6] = answerCallback;
        break;
    default:
        // Unknown aquarium command, only send callback
        output[6] = answerCallback;
        break;
}

return output;

if (msg.payload && msg.payload.callback_query_id) {
    msg.payload = {
        callback_query_id: msg.payload.callback_query_id,
        text: msg.payload.text || '',
        show_alert: msg.payload.show_alert || false
    };
    msg.topic = 'answerCallbackQuery';
    return msg;
}
return null;

node.warn(`[${msg.requestId}] Turning aquarium light ON`);

return [
    { payload: 'ON', topic: 'cmnd/sursaAcvariu/POWER' },
    {
        payload: {
            chatId: msg.chatId,
            type: 'message',
            content: '🐠 Aquarium light turned *ON*',
            options: {
                parse_mode: 'Markdown'
            }
        }
    }
];

node.warn(`[${msg.requestId}] Turning aquarium light OFF`);

return [
    { payload: 'OFF', topic: 'cmnd/sursaAcvariu/POWER' },
    {
        payload: {
            chatId: msg.chatId,
            type: 'message',
            content: '🐠 Aquarium light turned *OFF*',
            options: {
                parse_mode: 'Markdown'
            }
        }
    }
];

node.warn(`[${msg.requestId}] Toggling aquarium light`);

return [
    { payload: 'TOGGLE', topic: 'cmnd/sursaAcvariu/POWER' },
    {
        payload: {
            chatId: msg.chatId,
            type: 'message',
            content: '🐠 Aquarium light *toggled*',
            options: {
                parse_mode: 'Markdown'
            }
        }
    }
];

node.warn(`[${msg.requestId}] Getting aquarium light status`);

// Get state from global context
const state = global.get('aquarium_state') || {};

// Build status message
let statusText = '🐠 *Aquarium Light Status*\n\n';

const lightStatus = state.light_power || 'UNKNOWN';
const statusEmoji = lightStatus === 'ON' ? '💡' : (lightStatus === 'OFF' ? '⚫' : '❓');

statusText += `${statusEmoji} *Light*: ${lightStatus}\n`;

if (state.lastUpdate) {
    const lastUpdate = new Date(state.lastUpdate);
    statusText += `\n⏰ Last update: ${lastUpdate.toLocaleString()}\n`;
}

const inlineKeyboard = {
    inline_keyboard: [
        [
            { text: '💡 Turn ON', callback_data: '/aquarium_on' },
            { text: '⚫ Turn OFF', callback_data: '/aquarium_off' }
        ],
        [
            { text: '🔄 Toggle', callback_data: '/aquarium_toggle' },
            { text: '📊 Refresh Status', callback_data: '/aquarium_status' }
        ],
        [
            { text: '❓ Help', callback_data: '/aquarium_help' }
        ]
    ]
};

msg.payload = {
    chatId: msg.chatId,
    type: 'message',
    content: statusText,
    options: {
        parse_mode: 'Markdown',
        reply_markup: inlineKeyboard
    }
};

return msg;

node.warn(`[${msg.requestId}] Aquarium help requested`);

const helpText = `🐠 *Aquarium Light Control*\n\n` +
    `*Available Commands:*\n` +
