    `*Hardware:*\n` +
    `• Tasmota device (sursaAcvariu)\n` +
    `• Single relay control\n\n` +
    `*Quick Actions* ⬇️`;

const inlineKeyboard = {
    inline_keyboard: [
        [
            { text: '💡 Turn ON', callback_data: '/aquarium_on' },
            { text: '⚫ Turn OFF', callback_data: '/aquarium_off' }
        ],
        [
            { text: '🔄 Toggle', callback_data: '/aquarium_toggle' },
            { text: '📊 Status', callback_data: '/aquarium_status' }
        ],
        [
            { text: '🏠 Main Menu', callback_data: '/help' }
        ]
    ]
};

msg.payload = {
    chatId: msg.chatId,
    type: 'message',
    content: helpText,
    options: {
        parse_mode: 'Markdown',
        reply_markup: inlineKeyboard
    }
